static const char *riscv32_meta_mnemonic_name(nyasm_u32 mnemonic) {
   if (mnemonic >= COUNT_OF(riscv32_mnemonic_names)) {
      return "";
   }

   return riscv32_string(riscv32_mnemonic_names[mnemonic].name);
}

static nyasm_u32 riscv32_meta_brief(nyasm_u32 handle, char *text, nyasm_u32 capacity) {
   const brief_texts_row *row = riscv32_brief_texts + riscv32_iform_brief[RISCV32_HANDLE(handle)];
   text_output            out;
   u32                    index;

   text_start(&out, text, capacity);
   for (index = 0; index < row->count; ++index) {
      if (index) {
         put_character(&out, ' ');
      }

      put_text(&out, riscv32_string(riscv32_brief_words[row->first + index]));
   }

   return text_end(&out);
}

static nyasm_u32 riscv32_meta_feature_count(nyasm_u32 handle) {
   return riscv32_isa_sets[riscv32_iform_isa[RISCV32_HANDLE(handle)]].count;
}

static nyasm_u32 riscv32_meta_feature(nyasm_u32 handle, nyasm_u32 index, nyasm_u32 *last) {
   const isa_sets_row *set = riscv32_isa_sets + riscv32_iform_isa[RISCV32_HANDLE(handle)];
   u32                 item;

   *last = 1;
   if (index >= set->count) {
      return 0;
   }

   item  = riscv32_isa_items[set->first + index];
   *last = (item & FEATURE_LAST) != 0;
   return item & FEATURE_MASK;
}

static const char *riscv32_meta_feature_name(nyasm_u32 feature) {
   if (feature >= COUNT_OF(riscv32_feature_name_offsets)) {
      return "";
   }

   return (const char *)riscv32_feature_name_bytes + riscv32_feature_name_offsets[feature];
}

static nyasm_u32 riscv32_meta_trait_count(nyasm_u32 handle) {
   return riscv32_trait_lists[riscv32_iform_traits[RISCV32_HANDLE(handle)]].count;
}

static const char *riscv32_meta_trait_key(nyasm_u32 handle, nyasm_u32 index) {
   const trait_lists_row *list = riscv32_trait_lists + riscv32_iform_traits[RISCV32_HANDLE(handle)];

   if (index >= list->count) {
      return "";
   }

   return riscv32_string(riscv32_trait_items[list->first + index].key);
}

static const char *riscv32_meta_trait_value(nyasm_u32 handle, nyasm_u32 index) {
   const trait_lists_row *list = riscv32_trait_lists + riscv32_iform_traits[RISCV32_HANDLE(handle)];

   if (index >= list->count) {
      return "";
   }

   return riscv32_string(riscv32_trait_items[list->first + index].value);
}

static const char *riscv32_meta_trait(nyasm_u32 handle, const char *key) {
   const trait_lists_row *list = riscv32_trait_lists + riscv32_iform_traits[RISCV32_HANDLE(handle)];
   u32                    index;

   for (index = 0; index < list->count; ++index) {
      if (text_equal(riscv32_string(riscv32_trait_items[list->first + index].key), key)) {
         return riscv32_string(riscv32_trait_items[list->first + index].value);
      }
   }

   return 0;
}

static nyasm_u32 riscv32_meta_operand_count(nyasm_u32 handle) {
   return riscv32_iform_operands[RISCV32_HANDLE(handle)].count;
}

static nyasm_u32 riscv32_meta_operand(nyasm_u32 handle, nyasm_u32 index, nyasm_operand_info *info) {
   const iform_operands_row *span = riscv32_iform_operands + RISCV32_HANDLE(handle);
   const operand_rows_row   *row;

   if (index >= span->count) {
      return 0;
   }

   row               = riscv32_operand_rows + riscv32_operand_lists[span->first + index].row;
   info->register_id = row->register_;
   info->width       = row->width;
   info->kind        = row->kind;
   info->visibility  = row->visibility;
   info->access      = row->access;
   info->flags       = row->flags;
   return 1;
}

static const char *riscv32_meta_register_name(nyasm_u32 register_id) {
   if (register_id >= COUNT_OF(riscv32_registers)) {
      return "";
   }

   return riscv32_string(riscv32_registers[register_id].name);
}

static void riscv32_meta_effect_sets(nyasm_u32 handle, nyasm_effects *effects) {
   const access_records_row *record = riscv32_access_records + riscv32_iform_access[RISCV32_HANDLE(handle)];
   u32                       words  = BIT_WORDS(NYASM_RISCV32_ATOM_COUNT);

   effects->reads     = riscv32_vectors + record->reads * words;
   effects->writes    = riscv32_vectors + record->writes * words;
   effects->clobbers  = riscv32_vectors + record->clobbers * words;
   effects->zeroed    = riscv32_vectors + record->zeroed * words;
   effects->set       = riscv32_vectors + record->set * words;
   effects->undefined = riscv32_vectors + record->undefined * words;
   effects->words     = words;
   effects->reserved  = 0;
}

static const char *riscv32_meta_atom_name(nyasm_u32 atom) {
   if (atom >= NYASM_RISCV32_ATOM_COUNT) {
      return "";
   }

   return riscv32_string(riscv32_atoms[atom].name);
}

